 "content": "def transform(grid):
    nrows = len(grid)
    ncols = len(grid[0]) if grid else 0
    out = [row[:] for row in grid]
    for r in range(nrows):
        for c in range(ncols):
            if grid[r][c] == 3:
                # The design is symmetric under 180-degree rotation and reflection.
                # If the rotational counterpart is itself covered, use the horizontal counterpart.
                value = grid[nrows - 1 - r][ncols - 1 - c]
                if value == 3:
                    value = grid[r][ncols - 1 - c]
                out[r][c] = value
    return out
